CREATE TABLE core_rel.T_TRANSPORT_PLAN_CROSSDOCK_TRANSPORT_MOVEMENT_2 (
   tour_id                             VARCHAR(100)    NOT NULL COMMENT 'An internally generated identifier that uniquely identifies a specific transport tour_2 or vehicle route.',
   inbound_dispo_order_pos_sid         NUMBER          NOT NULL COMMENT 'The unique identifier (surrogate key) for the disposition position.',
   order_reference_nr                  VARCHAR(250)    NOT NULL COMMENT '14 digit number containing info about log-type (digits 1-2), main cross-dock (digits 3-5), delivery date at the cross-dock (digits 6-11) and receiving regional subsidiary (digits 12-14)',
   vehicle_id                          VARCHAR(20)     NOT NULL COMMENT 'The unique identifier of the vehicle used for transport.',
   product_variant_sid                 NUMBER          NOT NULL COMMENT 'The unique identifier of the product variant. (GTIN based )',
   transport_start_site_sid            NUMBER          COMMENT 'A unique identifier of the site where the transport starts ( supplier_2 warehouse or crossdock)',
   transport_end_site_sid              NUMBER          NOT NULL COMMENT 'unique identifier of the site where the transport ends (crossdock or RDC=',
   inbound_logistics_partner_name      VARCHAR(100)    COMMENT 'A name of hauler transporting goods',
   logistics_partner_name              VARCHAR(100)    COMMENT 'A name of hauler transporting goods',
   hauler_sid                          NUMBER          COMMENT 'The unique identifier of the delivering party, e.g. the supplier.',
   supplier_sid                        NUMBER          NOT NULL COMMENT 'A unique identifier for the logistics company (hauler) handling the transport.',
   dept_arrival_tmsp                   TIMESTAMP_LTZ   COMMENT 'The exact time a truck (LKW) arrives at the departure premises delivering the goods from the previous location_2',
   dept_checkin_tmsp                   TIMESTAMP_LTZ   COMMENT 'The time the driver officially checks in at the departure.This often happens shortly after arrival and involves submitting paperwork.',
   dept_departure_tmsp                 TIMESTAMP_LTZ   COMMENT 'The time when the truck leaves the  departure premises after all tasks (unloading, paperwork, etc.) are finished.',
   dept_gate_id                        VARCHAR(20)     COMMENT 'Destinatiom warehouse gate',
   dest_arrival_tmsp                   TIMESTAMP_LTZ   COMMENT 'The exact time a truck (LKW) arrives at the destination premises delivering the goods from the previous location_2',
   dest_checkin_tmsp                   TIMESTAMP_LTZ   COMMENT 'The time the driver officially checks in at the destination.This often happens shortly after arrival and involves submitting paperwork.',
   dest_departure_tmsp                 TIMESTAMP_LTZ   COMMENT 'The time when the truck leaves the destination premises after all tasks (unloading, paperwork, etc.) are finished.',
   dest_gate_id                        VARCHAR(20)     COMMENT 'Departure warehouse gate',
   pallet_cnt                          NUMBER          COMMENT 'A count of transported pallets',
   delay_reason_hauler_cd              VARCHAR(20)     COMMENT 'The code for the status_2 of the product.',
   dwh_created_tmsp                    TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
   dwh_updated_tmsp                    TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was last updated.',   
   CONSTRAINT PK_T_TRANSPORT_PLAN_CROSSDOCK_TRANSPORT_MOVEMENT PRIMARY KEY (tour_id, product_variant_sid) NOT ENFORCED 
)  COMMENT = 'The entity contains information regarding transport for all products of a disposition, i.e. which travel route a product takes.';
